Wrap `db.query` in Promise, then `async/await`:

```javascript
async function getUser(id) {
  const rows = await db.query('SELECT * FROM users WHERE id = ?', [id]);
  if (!rows.length) throw new Error('Not found');
  return rows[0];
}
```

Call it:

```javascript
// Option 1: try/catch
try {
  const user = await getUser(42);
  console.log(user);
} catch (err) {
  console.error(err);
}

// Option 2: .catch()
const user = await getUser(42).catch(err => { /* handle */ });
```

---

**If `db.query` no return Promise** (old callback-only driver), wrap first:

```javascript
function queryAsync(sql, params) {
  return new Promise((resolve, reject) => {
    db.query(sql, params, (err, rows) => {
      if (err) reject(err);
      else resolve(rows);
    });
  });
}

async function getUser(id) {
  const rows = await queryAsync('SELECT * FROM users WHERE id = ?', [id]);
  if (!rows.length) throw new Error('Not found');
  return rows[0];
}
```

---

Key changes:

- `err` callback → `throw` (caller catch via `try/catch`)
- `callback(null, result)` → `return result`
- Errors propagate up call stack automatically
